import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风泽中孚","description":"周易折中 - 风泽中孚","frontmatter":{"title":"风泽中孚","description":"周易折中 - 风泽中孚"},"headers":[],"relativePath":"zh/classics/zhezhong/067.md","filePath":"zh/classics/zhezhong/067.md"}'),h={name:"zh/classics/zhezhong/067.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="风泽中孚" tabindex="-1">风泽中孚 <a class="header-anchor" href="#风泽中孚" aria-label="Permalink to “风泽中孚”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈中孚序卦〉：“节而信之，故受之以《中孚》。《节》者，为之制节，使不得过越也。信而后能行，上能信守之，下则信从之，节而信之也。《中孚》所以次《节》也。为卦，泽上有风，风行泽上而感于水中，为中孚之象。感，谓感而动也。内外皆实而中虚，为中孚之象，又二五皆阳中实，亦为孚。义在二体，则中实；在全体，则中虚。中虚，信之本；中实，信之质。”</p><p>中孚：豚鱼吉，利涉大川，利贞。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>孚，信也。为卦二阴在内，四阳在外，而二五之阳皆得其中。以一卦言之为中虚，以二体言之为中实，皆孚信之象也。又下说以应上，上巽以顺下，亦为孚义。豚鱼无知之物，又木在泽上，外实内虚，皆舟楫之象。至信可感豚鱼，涉险难而不可以失其贞，故占者能致豚鱼之应，则吉而利涉大川，又必利于贞也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>豚躁鱼冥，物之难感者也。孚信能感于豚鱼，则无不至矣，所以吉也。忠信可以蹈水火，况涉川乎？守信之道在乎坚正，故利于贞也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：信发于中，谓之中孚。鱼者虫之幽隐，豚者兽之微贱。内有诚信，则虽微隐之物信皆及矣。既有诚信，光被万物，以斯涉难，何往不通？故曰“利涉大川”。信而不正，凶邪之道，故利在贞也。</p></li><li><p>苏氏轼曰：中孚，信也。而谓之中孚者，如羽虫之孚，有诸中而后能化也。内无阳不生，故必刚得中，然后为中孚也。</p></li><li><p>朱子语类：问：中孚，“孚”字与“信”字恐亦有别。 曰：伊川云“存于中为孚，见于事为信”，说得极好。因举字说，“孚”字从爪从子，如鸟抱子之象。今之“乳”字一邉从孚，葢中所抱者实有物也。中间实有物，所以人自信之。 问：中虚、信之本，中实、信之质如何？ 曰：只㸔虚实字，便见本质之异。中虚是无事时虚而无物，故曰中虚；自中虚中发出来皆是实理，所以曰中实。 又云：一念之间中无私主，便谓之虚；事皆不妄，便谓之实。不是两件事。</p></li><li><p>问：中孚，“孚”字与“信”字恐亦有别。 曰：伊川云“存于中为孚，见于事为信”，说得极好。因举字说，“孚”字从爪从子，如鸟抱子之象。今之“乳”字一邉从孚，葢中所抱者实有物也。中间实有物，所以人自信之。</p></li><li><p>问：中虚、信之本，中实、信之质如何？ 曰：只㸔虚实字，便见本质之异。中虚是无事时虚而无物，故曰中虚；自中虚中发出来皆是实理，所以曰中实。</p></li><li><p>又云：一念之间中无私主，便谓之虚；事皆不妄，便谓之实。不是两件事。</p></li><li><p>胡氏炳文曰：豚鱼至愚无知，惟信足以感之。大川至险不测，惟信足以济之。然信而或失其正则如盗贼相群，男女相私，士夫死党，小人出肺肝相示而遂背之，其为孚也，人为之伪，非天理之正，故又戒以利贞。</p></li><li><p>蔡氏清曰：豚鱼吉，承中孚云也。中孚便有以孚于物矣，不然乃为豚鱼之吉，而不为中孚者之吉矣。豚鱼是承中孚，故《彖传》曰“豚鱼吉，信及豚鱼也”。</p></li><li><p>吴氏曰愼曰：中孚豚鱼吉，卦辞连卦名为义，犹“同人于野”、“履虎尾”、“艮其背”之例。言人中心能孚信于豚鱼，则无所不感矣，故吉也。</p></li></ul><p>象曰：泽上有风，中孚；君子以议狱缓死</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>风感水受，中孚之象。议狱缓死，中孚之意。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽上有风，感于泽中水，体虚故风能入之。人心虚，故物能感之。风之动乎泽，犹物之感于中，故为中孚之象。君子观其象，以议狱与缓死。君子之于议狱，尽其忠而已；于决死，极于恻而已。故诚意常求于缓、寛也。于天下之事，无所不尽其忠，而议狱缓死最其大者也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏万里曰 ：风无形而能鼔幽濳，诚无象而能感人物。中孚之感，莫大于好生不杀。议狱者，求其入中之出；缓死者，求其死中之生也。</p></li><li><p>项氏安世曰 ：狱之将决则议之，其既决则又缓之，然后尽于人心。王听之，司寇听之，三公听之。议狱也，旬而职听，二旬而职听，三月而上之。缓死也，故狱成而孚，输而孚。在我者尽，故在人者无憾也。</p></li><li><p>徐氏几曰 ：象言刑狱。五卦噬嗑、丰以其有离之明、震之威也。贲次噬嗑，旅次丰。离明不易，震皆反为艮矣。盖明贵无时不然，威则有时当止。至于中孚，则全体似离，互体有震、艮，而又兑以议之，巽以缓之。圣人即象垂教，其忠厚恻怛之意见于谨刑如此。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>风之入物也，不独平地草木为之披拂，岩谷窍穴为之吹吁，即积水重阴之下，亦因之而冻解冰释焉。此所以为至诚无所不入之象也。民之有狱，犹地之有重阴也。王者体察天下之情隐，至于议狱缓死，然后其至诚无所不入矣。</p><p>彖曰：中孚 柔在内而刚得中，说而巽，孚乃化邦也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体卦徳释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>二柔在内，中虚为诚之象；二刚得上下体之中，中实为孚之象。卦所以为中孚也。说而巽，以二体言卦之用也。上巽下说，为上至诚以顺巽于下，下有孚以说从其上。如是其孚，乃能化于邦国也。若人不说从，或违拂事理，岂能化天下乎？</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：孚者，覆乳之象也。夫覆乳者，必刚外而柔内，虽柔内非阳则不生，故刚得中而为孚也。</p></li><li><p>王氏宗传曰：以成卦观之，在二体则为中实，在全体则为中虚。盖中不虚则有所累，有所累害于信者也；中不实则无所主，无所主则又失其信矣。故曰中孚。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>柔在内而刚得中，其义甚精。非柔在内，则中不虚矣；非刚得中，则中又不实矣。地至虚也，然惟阴中有阳，故受天气而生物；月至虚也，然惟水阴根阳，故受日光而发照。物之雌牝受阳精而胎化者亦然。此卦之名所以取于乳卵者此也。老子亦曰：“仿兮佛，其中有物；窈兮冥，其中有精。真精之中，其中有信。”盖见及此也。又案，无妄天徳也，天徳实实则虚矣，故曰无妄，言其虚也；中孚地徳也，地徳虚虚则实矣，故曰中孚，言其实也。惟无妄之主于虚也，故六爻之义皆贵乎无谋望作为之私，反是则有妄矣；惟中孚之主于实也，故六爻之义皆贵乎有诚心实徳之积，反是则非孚矣。二卦之义实相表里。</p><p>豚鱼吉，信及豚鱼也；利涉大川，乘木舟虚也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦象言。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>信能及于豚鱼，信道至矣，所以吉也。以中孚涉险难，其利如乘木济川，而以虚舟也。舟虚则无沈覆之患，卦虚中为虚舟之象。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：用中孚以涉难，若乘木舟虚也。</p></li><li><p>郑氏湘卿曰：仁及草木，言草木难仁也；诚动金石，言金石难诚也；信及豚鱼，言豚鱼难信也。</p></li><li><p>蔡氏清曰：木在泽上，既为乘木之象，外实内虚，又为舟虚之象。</p></li><li><p>吴氏曰慎曰：豚鱼吉，葢信及豚鱼者之吉，非豚鱼吉也。故在卦辞，不可以“豚鱼吉”三字为句，当以“中孚豚鱼”为读。彖传“信及豚鱼”，即“中孚豚鱼”也。</p></li></ul><p>中孚以利贞，乃应乎天也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>信而正则应乎天矣。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>中孚而贞，则应乎天矣。天之道，孚贞而已。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰：天道不容伪。</li></ul><p>初九：虞吉，有他不燕。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>当中孚之初，上应六四，能度其可信而信之，则吉。复有他焉，则失其所以度之之正，而不得其所安矣。戒占者之辞也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>九当中孚之初，故戒在审其所信。虞度也，度其可信而后从也。虽有至信，若不得其所，则有悔咎。故虞度而后信，则吉也。既得所信，则当诚一，若有他，则不得其燕安矣。燕安，裕也。有他，志不定也。人志不定，则惑而不安。初与四为正应，四巽体而居正，无不善也。爻以谋始之义大，故不取相应之义。若用应，则非虞也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苟氏爽曰：虞，安也。初应于四，宜自安虞，无意于四则吉，故曰“虞吉”也。有意于四，则不安，故曰“有他不燕”也。</p></li><li><p>项氏安世曰：中孚六爻皆不取外应，孚在其中，无待于外也。初九安处于下，不假他求，何吉如之？苟变其志，动而求孚于四，则失其安也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>荀氏、项氏说于易例、卦义皆合。盖易例初九应六四，义无所取。如屯之“磐桓”、贲之“贲趾”，皆不取应四为义；颐之“朵颐”，则反以应四为累。惟损益之初，则适当益上报上之卦时，义不同也。此卦之义主于中有实德，不愿乎外，故六爻无应者吉，有应者凶。初之“虞吉”，谓其有以自守自安也。礼有虞祭，亦安之义也。燕亦安也，虞则燕，不虞则不燕矣。“有他不燕”，正与大过九四“有他吝”同。九四下应初六为“有他”，初九上应六四亦为“有他”也。</p><p>象曰：初九虞吉；志未变也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>当信之始，志未有所存，而虞度所信，则得其正是以吉也。盖其志未有变动，志有所从，则是变动。虞之不得其正矣，在初言求所信之道也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>志未变，言其实心不失也。志变，则有他矣。</p><p>九二：鸣鹤在阴，其子和之；我有好爵，吾与尔靡之。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>九二中孚之实，而九五亦以中孚之实应之，故有鹤鸣子和，我爵尔靡之象。鹤在阴，谓九居二；好爵，谓得中；靡与縻同，言懿德人之所好，故好爵虽我之所独有，而彼亦系恋之也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二刚实于中孚之至者也。孚至则能感通，鹤鸣于幽隐之处，不闻也，而其子相应和，中心之愿相通也。好爵我有，而彼亦系慕，说好爵之意同也。有孚于中，物无不应，诚同故也。至诚无远近幽深之间，故《系辞》云：“善则千里之外应之，不善则千里违之。”言诚通也。至诚感通之理，知道者为能识之。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：九二体刚，处于卦内，又在三四重阴之下，而履不失中，是不徇于外，自任其真者也。处于幽昧而行不失信，则声闻于外，为同类之所应焉。如鹤之鸣于幽远，则为其子所和也。靡，散也，不私权利，惟德是与。若我有好爵，愿与尔贤者分散而共之，故曰“我有好爵，吾与尔靡之”。</p></li><li><p>王氏安石曰：君子之言行至诚而善，则虽在幽远，为己类者亦以至诚从而应之，中孚之至也。</p></li><li><p>苏氏轼曰：中孚必正而一，静而久。而初九、六四、六三、上九有应而相求，皆非所谓正而一、静而久者也。惟九二端悫无求，而物自应焉。</p></li><li><p>张氏浚曰：二处二阴下，为在阴，其子和之谓初。</p></li><li><p>郑氏汝谐曰：二独无应，若未信于人而爻之最吉莫二若也。自耀者其实丧，自晦者其德章。无心于感物，而物无不感者，至诚之道也。二以刚履柔，其居得中，且伏于二阴之下，葢静晦而无求者。无求而物自应，故鹤鸣在阴，而其子和之者，感以天也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>易例中凡言“子”言“童”者，皆初之象。故张氏以其“子和之”为初者近是。好爵谓㫖酒也，靡谓醉也。九二有刚中之实徳，无应于上，而初与之同德，故有鹤鸣子和、好爵尔靡之象。言父子明不出户庭也，言尔我明不逾同类也。《诗》云：“鹤鸣于九皋，声闻于天。”则居爽垲之地而声及远矣。处于阴而子和，则不求远闻可知。又曰：“我有㫖酒，嘉賔式燕以衎。”则同乐者众矣。吾与尔靡，则惟二人同心而已。君子之实德实行，不务于远而脩于迩，故《系辞传》两言“况其迩者乎”，然后推广而极言之。</p><p>象曰：其子和之，中心愿也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>中心愿，谓诚意所愿也，故通而相应。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：荀子所谓“同焉者合，类焉者应”也。</p></li><li><p>程氏敬承曰 ：鹤之鸣由中而发，子之和亦根心而应，故曰“中心愿”。愿出于中，乃孚之至也。</p></li></ul><p>六三：得敌，或鼓或罢，或泣或歌。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>敌，谓上九。信之穷者，六三阴柔不中正，以居说极而与之为应，故不能自主，而其象如此。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>敌对，敌也。谓所交孚者正应上九是也。三四皆以虚中为成孚之主，然所处则异。四得位居正，故亡匹以从上；三不中失正，故得敌以累志。以柔说之质，既有所系，惟所信是从。或鼓张，或罢废，或悲泣，或歌乐，动息忧乐皆系乎所信也。惟系所信，故未知吉凶，然非明逹君子之所为也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰：人惟信不足，故言行之间变动不常如此。</p></li><li><p>李氏简曰：六三之得敌，以其有私系之心也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>诸爻独三上有应，有应者动于外也，非中孚也。人心动于外，则忧乐皆系于物。鼓、罢、泣、歌，喻其不能坦然自安，葢初九虞、燕之反也。</p><p>象曰：或鼓或罢，位不当也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>居不当位，故无所主，唯所信是从。所处得正则所信有方矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：六三居不当位，心无所主，故或鼔或罢而不定。若初九则不如是也。</li></ul><p>六四：月几望，马匹亡，无咎。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>六四居阴得正位，近于君，为月几望之象。马匹谓初与已为匹，四乃绝之，而上以信于五，故为马匹亡之象。占者如是，则无咎也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四为成孚之主，居近君之位，处得其正，而上信之至，当孚之任者也。如月之几望，盛之至也。已望则敌矣，臣而敌君，祸败必至，故以几望为至盛。马匹亡，四与初为正应匹也。古者驾车用四马，不能备纯色，则两服两骖各一色，又小大必相称，故两马为匹，谓对也。马者行物也，初上应四而四亦进从五，皆上行，故以马为象。孚道在一，四既从五，若复下系于初，则不一而害于孚，为有咎矣。故马匹亡则无咎也。上从五而不系于初，是亡其匹也。系初则不进，不能成孚之功也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰：匹亦敌之类也，得敌则匹亡，其道相反也。《彖传》言柔在内，而爻则其道相反，葢卦爻取义有不得而同者也。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>易中六四应初九而义有取焉者，皆上不遇九五者也。如六四遇九五，则以从上为义而应非所论。易例皆然，而此爻尤明。葢孚不容于有二，况居大臣之位者乎？月几望者，阴受阳光承五之象也；马匹亡者，无有私群远初之象也。自坤卦牝马以得主为义，而其下曰“东北丧朋”，东北者近君之位也，中孚之四当之矣。</p><p>站长：晚清尚秉和著有《周易尚氏学》，其中论点认为，西汉时期的易学家孟喜、荀爽皆做「月既望」，详情可看本站的《周易尚氏学》。</p><p>象曰：马匹亡，绝类上也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>绝其类而上从五也，类谓应也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：坤以丧朋为有庆，中孚之四以绝类为无咎。</p></li><li><p>赵氏玉泉曰 ：马匹亡者，四有柔正之德，故能绝初之党类，而上以信于五也。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>三与四皆卦所谓中虚者也。其居内以成中虚之象同，其得应而有匹敌者亦同。然三心系于敌而四志绝乎匹者，三不正而四正也。又六四承九五者多吉，六三应上九者多凶，易例如此。</p><p>九五：有孚挛如，无咎。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九五刚健中正，中孚之实而居尊位，为孚之主者也。下应九二，与之同德，故其象占如此。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>五居君位，人君之道当以至诚感通天下，使天下之心信之固结如拘挛然，则为无咎也。人君之孚不能使天下固结如是，则亿兆之心安能保其不离乎？</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：处中诚以相交之时，居尊位以为群物之主，信何可舎？故有孚挛如，乃得无咎。</p></li><li><p>胡氏瑗曰：居尊而有中正之德，是有至诚至信之心，发之于内而交于下，以挛天下之心。上下内外皆以诚信相通，是得为君之道，何咎之有？</p></li><li><p>郭氏雍曰：孚之道无不通，亦无不感，可以通天下之志，至于固结挛如，是以无咎。九五君位，足以感通天下，又无私应之累，故直曰“有孚挛如”而已。</p></li><li><p>胡氏炳文曰：六爻不言孚，惟九五言之。九五，孚之主也。</p></li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>此爻是《彖》所谓“孚乃化邦”者也。人君之孚与在下者不同，居下位者中有实德不迁于外而已，人君则以孚天下为实德。故必诚信固结于天下，然后为无咎也。此爻义与小畜之九五同，其为臣者“月几望”之义亦同，但彼主于君臣相畜，而此主于君臣相孚尔。要之，“富以其邻”者，即“孚乃化邦”之说，而“君子征凶”者，亦即“马匹亡”之意也。</p><p>象曰：有孚挛如，位正当也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>五居君位之尊，由中正之道，能使天下信之如拘挛之固，乃称其位。人君之道当如是也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰 ：以其正当尊位，故戒以系信乃得无咎。</li></ul><p>上九：翰音登于天，贞凶。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>居信之极而不知变，虽得其贞，亦凶道也。故其象占如此。鸡曰翰音，乃巽之象。居巽之极为登于天，鸡非登天之物而欲登天，信非所信而不知变，亦犹是也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>翰音者，音飞而实不从。处信之终，信终则衰，忠笃内丧，华美外飏，故云“翰音登天，正亦灭矣”。阳性上进，风体飞飏，九居中孚之时，处于最上，孚于上进而不知止者也。其极至于羽翰之音登闻于天，贞固于此而不知变，凶可知矣。夫子曰：“好信不好学，其蔽也贼。”固守而不通之谓也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：翰，高飞也。飞音者，音飞而实不从之谓也。居卦之上，处信之终，信终则衰，忠笃内丧，华美外掦，故曰“翰音登于天”也。</p></li><li><p>胡氏瑗曰：翰者，鸟羽之高飞也。上九在一卦之上，居穷极之地，是无纯诚之心、笃实之道，徒务其虚声，外饰以矫伪为尚，如鸟之飞登于天，徒闻其虚声而已。</p></li><li><p>苏氏轼曰：翰音，飞且鸣者也。处外而居上，非中孚之道。飞而求显，鸣而求信者也。故曰“翰音登于天”。九二在阴而子和，上九飞鸣而登天，其道葢相反也。</p></li><li><p>朱氏震曰：巽为鸡，刚其翰也，柔其毛也。翰，羽翮也，鸡振其羽翮而后出于声，翰音也。</p></li><li><p>郑氏汝谐曰：翰音登天者，声闻过情，君子耻之。</p></li><li><p>章氏潢曰：二居兑泽，故曰“在阴”。上为巽风，故曰“于天”。孚于中也，则鸣鹤自有子和；孚于外也，则翰音徒登于天。然则中孚岂可以人伪为之哉？</p></li></ul><p>象曰：翰音登于天，何可长也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>守孚至于穷极而不知变，岂可长久也？固守而不通，如是则凶也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：虚声无实，何可久长。</p></li><li><p>侯氏行果曰 ：穷上失位，信不由中，有声无实，虚华外扬，是翰音登天也。虚音登天，何可久也？</p></li><li><p>胡氏瑗曰 ：上九徒以虚声外饰，无纯诚笃实之行。以此而往，愈久愈凶，故圣人戒之曰“何可长”如此。盖欲人改过反诚，以信实为本也。</p></li><li><p>项氏安世曰 ：上九巽极而躁，不正不中，内不足而求孚于外，声闻过情。其涸也可立而待，愈久愈凶，何可长也。</p></li></ul>',127)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
